head.script:
/***************************************************************************************
* 시스템명 : 문서접수관리
* 업무명   : 업무공통
* 파일명   : as-is : QA0101.xml
* 파일명   : to-be : CM0101100M.xml
* 작성자   : YANG
* 작성일   : 2024.12.10
*
* 설 명 : 문서접수관리
*---------------------------------------------------------------------------------------
* 변경일 변경자 변경내역
*---------------------------------------------------------------------------------------
* 2024.12.10 YANG	최초 프로그램 작성
*
*---------------------------------------------------------------------------------------
****************************************************************************************/

scwin.v_PMinwonFg   	    = "1";	//민원서류구분 
scwin.v_PFormloadFg 	    = "S";  //디비젼안에 폼로드시 사용할 변수 S: 신규, J: 조회
scwin.v_PJeopstNo   	    = "" ;
scwin.v_WindowYn      	    = "N";
scwin.v_SiisPgm       	    = "" ; 
scwin.v_initGubunYn   	    = 0  ; 
scwin.v_PMinwonDocCd	    = "" ;
scwin.v_PMinwonDocNm 	    = "" ;
scwin.v_PMinwonDocChkFg     = true;
scwin.v_JeopsuNo            = "" ; 

/*******************************************************************************
 * FUNCTION 명 : onpageload
 * FUNCTION 기능설명 : 화면 페이지 로드
*******************************************************************************/
scwin.onpageload = async function() 
{
	debugger;
	scwin.v_Title=true
	// sub 화면 실행때문에 await 으로 실행
   	await com.gfn_LoadForm();
   	scwin.fn_InitComboBoxForCommonCode();
   	scwin.fn_Init();   
   	if (!com.gfn_IsNull(scwin.v_JeopsuNo)) {  // parameter 가 있는 경우 자동 조회 처리
		// scwin.v_JeopsuNo = scwin.v_ParamJeopsuNo;
   	    dma_MinwonJeopsuJohoeJogeon.set("JEOPSU_NO", scwin.v_JeopsuNo);

   	    scwin.btn_Johoe_onclick(); 
   	}
};

/*******************************************************************************
 * FUNCTION 명 : fn_Init
 * FUNCTION 기능설명 : 화면 초기화.
*******************************************************************************/
scwin.fn_Init = function()
{   
    if (com.gfn_SsMinwonJeopsuFg() != "1" && com.gfn_SsMinwonJeopsuFg() != "2" && 
        com.gfn_SsMinwonJeopsuFg() != "3" && com.gfn_SsMinwonJeopsuFg() != "4" ){
        scwin.v_PMinwonFg = "2"; // '재활보상'으로 기본 셋팅 수정, 2024.04.02
    }else{    
        // scwin.v_PMinwonFg = com.gfn_SsMinwonJeopsuFg();
		scwin.v_PMinwonFg = "2";	// 징수 담당자도 재활보상으로 기본 세팅
	}

	 // 데이터셋 초기화
	scwin.fn_InitAllDataSet();

	scwin.cob_MinwonJeopsuJohoeJogeon_minwonFg_onviewchange();
	//cob_MinwonJeopsuJohoeJogeon_minwonFg.trigger("onviewchange");

	dlt_MinwonFg.setColumnFilter("GT_CD<>8");
    cob_MinwonJeopsuJohoeJogeon_minwonFg.focus();
    scwin.v_initGubunYn = 1 ; 

	dma_MinwonJeopsuJohoeJogeon.reform();
	dlt_MinwonFg.reform();
};

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_InitAllDataSet
 * FUNCTION 기능설명 : 데이터셋 초기화.
*******************************************************************************/
scwin.fn_InitAllDataSet = function()
{
	//민원접수조회조건 DataSet
	dma_MinwonJeopsuJohoeJogeon.setEmptyValue();	
	dma_MinwonJeopsuJohoeJogeon.set("MINWON_FG", scwin.v_PMinwonFg);
	dma_MinwonJeopsuJohoeJogeon.set("JEOPSU_NO", com.gfn_SsJisaCd() + com.substr(com.gfn_GetDate(), 0, 4));	
};

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_InitComboBoxForCommonCode
 * FUNCTION 기능설명 : 콤보박스, 공통코드 세팅
*******************************************************************************/
scwin.fn_InitComboBoxForCommonCode = function()
{
	// 민원서류구분 코드
	var codeOptions = [
		{ code : "Q0001", compID : "cob_MinwonJeopsuJohoeJogeon_minwonFg", dataNm : "dlt_MinwonFg" }
	];

	com.setCommonCode( codeOptions, function(){
		com.dataListFilter("dlt_MinwonFg", "GT_CD == '2' || GT_CD == '4' || GT_CD == '9'");  // 재활, 법원문서, 일반문서
		dlt_MinwonFg.setCellData( dlt_MinwonFg.getMatchedIndex("GT_CD", "2" )[0], "GT_CD_NM1", "재활보상");  // 코드명 변경
	});
};

/*******************************************************************************
 * FUNCTION 명 : scwin.cob_MinwonJeopsuJohoeJogeon_minwonFg_onviewchange
 * FUNCTION 기능설명 : 선택한 민원구분에 해당하는 민원접수화면을 출력
*******************************************************************************/
scwin.cob_MinwonJeopsuJohoeJogeon_minwonFg_onviewchange = function(info) 
{	
	if (!com.gfn_IsNull(info) && !com.gfn_IsNull(info.btn_Johoe) && info.btn_Johoe == true) {
		scwin.v_PFormloadFg = "J";
	} else {
		scwin.v_PFormloadFg = "S";
	}

	scwin.v_PMinwonFg = dma_MinwonJeopsuJohoeJogeon.get("MINWON_FG"); //민원서류구분 

	var v_SiisFg     = true;	
	var v_PopFg      = true;		
	var v_GyeolJaeFg = true;

	switch (scwin.v_PMinwonFg) {
	    case "4" : v_SiisFg     = false;
				   wfr_CommonTitle.getWindow().txb_Title.setValue("법원문서접수관리");
	    break;
	    case "9" : v_SiisFg     = false;	
				   v_PopFg      = false;	
				   v_GyeolJaeFg = false;
				   wfr_CommonTitle.getWindow().txb_Title.setValue("일반문서접수관리");
		break;
		default:
				  v_SiisFg     = false;		
				  wfr_CommonTitle.getWindow().txb_Title.setValue("보상민원접수관리");
		break;		  	
	}

	scwin.fn_ButtonVisible(v_SiisFg, v_PopFg, v_GyeolJaeFg);
};

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_ButtonVisible
 * FUNCTION 기능설명 : 선택한 민원구분에 따른 버튼 비/활성화
*******************************************************************************/
scwin.fn_ButtonVisible = function(v_SiisFg, v_PopFg, v_GyeolJaeFg) 
{
	// SIIS장애건조회 버튼
	if (v_SiisFg) {
		btn_MinwonJeopsuJohoeJogeon_SIISJangaeJohoe.show();
	} else {
		btn_MinwonJeopsuJohoeJogeon_SIISJangaeJohoe.hide();
	}	

	// 접수번호조회 팝업버튼
	if (v_PopFg) {
		btn_MinwonJeopsuJohoeJogeon_SelectMinwonJeopsuNoPup.show();
	} else {
		btn_MinwonJeopsuJohoeJogeon_SelectMinwonJeopsuNoPup.hide();
	}	

	if (scwin.v_PFormloadFg == "S") {		
		mae_MinwonJeopsuJohoeJogeon_jeopsuNo.setValue(com.gfn_SsJisaCd() + com.substr(com.gfn_GetDate(), 0, 4));
	}

	scwin.fn_SubWindowLoad();
};

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_ButtonVisible
 * FUNCTION 기능설명 : 선택한 민원구분에 따른 버튼 비/활성화
*******************************************************************************/
scwin.fn_SubWindowLoad = function() 
{
	var v_Row  = dlt_WindowPath.getMatchedIndex("MINWON_FG", scwin.v_PMinwonFg);

	var src = dlt_WindowPath.getCellData(v_Row[0], "W_ID");
	div_import_1_q_qa.setSrc(src);

	gyeoljaeBar.gfn_InitGtGyeoljaeInfo();
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_WindowRefresh
 * FUNCTION 기능설명 : 결재처리 후 refresh
*******************************************************************************/
scwin.fn_WindowRefresh = function() 
{	
	// 결재 영역
	div_import_1_q_qa.getWindow().scwin.fn_RetrieveMinwonJeopsuInfo(dma_MinwonJeopsuJohoeJogeon.get("JEOPSU_NO"));
}

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_MinwonJeopsuJohoeJogeon_SelectMinwonJeopsuNoPup_onclick
 * FUNCTION 기능설명 : 민원접수정보 팝업
*******************************************************************************/
scwin.btn_MinwonJeopsuJohoeJogeon_SelectMinwonJeopsuNoPup_onclick = async function(obj) 
{

	if (dma_MinwonJeopsuJohoeJogeon.get("MINWON_FG") != "4") {
		 var param = "v_Jeopsu_No = " + mae_MinwonJeopsuJohoeJogeon_jeopsuNo.getValue();
		 param += " v_Minwon_Fg	  = " + cob_MinwonJeopsuJohoeJogeon_minwonFg.getValue();

		 var v_MinwonJeopsuInfo	= Array();
		 v_MinwonJeopsuInfo		= await com.gfn_Dialog("/ui/sia/biz/cm/cm00/CM0001720P.xml", param, 1400, 620, "민원접수내역검색");

		 if(!com.gfn_IsNull(v_MinwonJeopsuInfo[0])) {
			mae_MinwonJeopsuJohoeJogeon_jeopsuNo.setValue(v_MinwonJeopsuInfo[0]);
			mae_MinwonJeopsuJohoeJogeon_jeopsuNo.commit();

			await scwin.btn_Johoe_onclick();
		 }	
		 mae_MinwonJeopsuJohoeJogeon_jeopsuNo.focus();
	} else {
		var v_Flag = "click";		  
		var v_Param  = "v_JeopsuNo=" + mae_MinwonJeopsuJohoeJogeon_jeopsuNo.getValue().replace(/[\-]/g, "");
		v_Param += " v_DateGubun=" + "4";

		var v_SongMuMinwonJeopsuInfo = Array();
		v_SongMuMinwonJeopsuInfo = await za.cfn_GetSongmuMinwonInfo(v_Flag, v_Param);	

		if (!com.gfn_IsNull(v_SongMuMinwonJeopsuInfo[0])) {
			mae_MinwonJeopsuJohoeJogeon_jeopsuNo.setValue(v_SongMuMinwonJeopsuInfo[8]);
			mae_MinwonJeopsuJohoeJogeon_jeopsuNo.commit();
			await scwin.btn_Johoe_onclick();
		 }	
		 mae_MinwonJeopsuJohoeJogeon_jeopsuNo.focus();		
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_MinwonJeopsuJohoeJogeon_SIISJangaeJohoe_onclick
 * FUNCTION 기능설명 : 4대보험연계장애건접수목록을 조회할 수 있는 화면을 Open
*******************************************************************************/
scwin.btn_MinwonJeopsuJohoeJogeon_SIISJangaeJohoe_onclick = async function(e)
{
    var param = "scwin.v_JeopsuNo="+ dma_MinwonJeopsuJohoeJogeon.get("JEOPSU_NO");

	//await com.gfn_Alert("준비중입니다.");
	/*
	해당건 가입납부에서만 처리함
    var v_RetStr = Array();
    v_RetStr = com.gfn_Dialog("q_qa::QA0116.xml",param);
    if (!com.gfn_IsNull(v_RetStr[0])) {
		dma_MinwonJeopsuJohoeJogeon.set("JEOPSU_NO", v_RetStr[0]);
		scwin.btn_Johoe_onclick();
	} else {
		mae_MinwonJeopsuJohoeJogeon_jeopsuNo.focus();
	}
	*/
}	

/*******************************************************************************
 * FUNCTION 명 : scwin.btn_Johoe_onclick
 * FUNCTION 기능설명 : 민원접수조회조건에 따른 접수정보를 조회
*******************************************************************************/
scwin.btn_Johoe_onclick = async function(e) 
{ 
	var v_JeopsuNo1 = dma_MinwonJeopsuJohoeJogeon.get("JEOPSU_NO").replace(/[\-]/g, "");
	if (com.gfn_IsNull(v_JeopsuNo1)) {
		var v_Msg = ["접수번호"];
		await com.gfn_MsgAlert("MZZA018", v_Msg); //필수 입력 항목입니다. @ 항목을 입력하십시오.

		mae_MinwonJeopsuJohoeJogeon_jeopsuNo.focus();
		return;
	}

	scwin.fn_Search();
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_Search
 * FUNCTION 기능설명 : 조회
*******************************************************************************/
scwin.fn_Search = function(action) 
{
	/*
	var srvId		 = "";
	var strURL		 = "";
	var strinDsList	 = "";
	var stroutDsList = "";
	var strArgument	 = "";
	var strCallback  = "scwin.fn_CallBack";

	switch(action) {

		case "RetrieveMinwonFgInfoCmd" 	:
			srvId		 = "RetrieveMinwonFgInfoCmd";
			strURL		 = "kcw.q.qa.cmd.RetrieveMinwonFgInfoCmd.do";
			strinDsList	 = "dma_MinwonJeopsuJohoeJogeon=dma_MinwonJeopsuJohoeJogeon";
			stroutDsList = "dma_MinwonFgJohoe=dma_MinwonFgJohoe";		
		break;		
	}

	com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, false, true, true);
	*/

	// 민원구분 조회
	dma_MinwonFgJohoe.setEmptyValue();
	dma_MinwonJeopsuJohoeJogeon.set("JEOPSU_NO", dma_MinwonJeopsuJohoeJogeon.get("JEOPSU_NO").replace(/[\-]/g, ""));
	com.executeSubmission(sbm_CM0101100M_E001);
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_CallBack
 * FUNCTION 기능설명 : 콜백함수
*******************************************************************************/ 
scwin.fn_CallBack = async function(e)
{
	var errorCode = com.getResultCode(e);

	// Error 인 경우 후 처리를 하지 않는다
	if(errorCode != "S") {
		return;
	}

	var srvId = e.id;
	srvId = srvId.substring(srvId.indexOf("sbm_"), srvId.length);
	if(srvId == "sbm_CM0101100M_E001") {  // 민원구분 조회

		dma_MinwonJeopsuJohoeJogeon.set("JEOPSU_NO", dma_MinwonJeopsuJohoeJogeon.get("JEOPSU_NO").replace(/[\-]/g, ""));
		scwin.v_PJeopstNo = dma_MinwonJeopsuJohoeJogeon.get("JEOPSU_NO");

		if (!com.gfn_IsNull(dma_MinwonFgJohoe.get( "MINWON_FG"))) {			
			if (scwin.v_PMinwonFg == dma_MinwonFgJohoe.get("MINWON_FG") && com.gfn_IsNull(scwin.v_JeopsuNo)) {				

				div_import_1_q_qa.getWindow().scwin.fn_RetrieveMinwonJeopsuInfo(scwin.v_PJeopstNo);
			} else { // 민원구분이 바뀐경우
				//dma_MinwonJeopsuJohoeJogeon.FireEvent = false;
				dma_MinwonJeopsuJohoeJogeon.set("MINWON_FG", dma_MinwonFgJohoe.get("MINWON_FG")); //민원서류구분 
				//dma_MinwonJeopsuJohoeJogeon.FireEvent = true;				

				scwin.cob_MinwonJeopsuJohoeJogeon_minwonFg_onviewchange({"btn_Johoe":true});
				if (!com.gfn_IsNull(scwin.v_JeopsuNo)) {
				    scwin.v_JeopsuNo = "" ; 
				}
			}	
		} else {
			if (scwin.v_PMinwonFg == "9") { //일반문서

				div_import_1_q_qa.getWindow().scwin.fn_RetrieveMinwonJeopsuInfo(scwin.v_PJeopstNo);
			} else {
				await com.gfn_Alert("접수번호가 유효하지 않습니다.");
				mae_MinwonJeopsuJohoeJogeon_jeopsuNo.focus();
			}
		}
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_Close
 * FUNCTION 기능설명 : 화면 닫기 (MDI를 닫을 때 호출)
*******************************************************************************/ 
scwin.fn_Close = function() {
	//ds변경여부 판단.
	var dsArr = Array();
	if (cob_MinwonJeopsuJohoeJogeon_minwonFg.getValue() != "9") {

		dsArr[0] = div_import_1_q_qa.getWindow().dma_JeopsuInfo;

		return com.gfn_IsUpdatedDataset(dsArr); 
	}else{
	    dsArr[0] = div_import_1_q_qa.getWindow().ds_IlbanMunseoJeopsuInfo;

		return com.gfn_IsUpdatedDataset(dsArr); 
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.mae_MinwonJeopsuJohoeJogeon_jeopsuNo_onblur
 * FUNCTION 기능설명 : 접수번호 blur
*******************************************************************************/ 
scwin.mae_MinwonJeopsuJohoeJogeon_jeopsuNo_onblur = function(e)
{   
	/*
	if (cob_MinwonJeopsuJohoeJogeon_minwonFg.getValue() != "9") {
	    var Value = com.gfn_GetMaskFullValue("mae_MinwonJeopsuJohoeJogeon_jeopsuNo").replace(/[\-]/g, "");
        mae_MinwonJeopsuJohoeJogeon_jeopsuNo.setValue(Value);
    }    
	*/
}

/*******************************************************************************
 * FUNCTION 명 : scwin.mae_MinwonJeopsuJohoeJogeon_jeopsuNo_onviewchange
 * FUNCTION 기능설명 : 접수번호 변경
*******************************************************************************/ 
scwin.mae_MinwonJeopsuJohoeJogeon_jeopsuNo_onviewchange = function(info) {
	if (cob_MinwonJeopsuJohoeJogeon_minwonFg.getValue() != "9") {
	    var Value = com.gfn_GetMaskFullValue("mae_MinwonJeopsuJohoeJogeon_jeopsuNo").replace(/[\-]/g, "");
        mae_MinwonJeopsuJohoeJogeon_jeopsuNo.setValue(Value);
    }    
};


/*******************************************************************************
 * FUNCTION 명 : scwin.mae_MinwonJeopsuJohoeJogeon_jeopsuNo_onkeydown
 * FUNCTION 기능설명 : 접수번호 keydown
*******************************************************************************/ 
scwin.mae_MinwonJeopsuJohoeJogeon_jeopsuNo_onkeydown = async function(e)
{
	if (e.keyCode == 13) {
		// keyDown이벤트가 change이벤트보다 먼저발생하기때문에 강제 설정해준다.
		dma_MinwonJeopsuJohoeJogeon.set("JEOPSU_NO", com.gfn_GetMaskFullValue("mae_MinwonJeopsuJohoeJogeon_jeopsuNo").replace(/[\-]/g, ""));

		if (!com.gfn_IsNull(dma_MinwonJeopsuJohoeJogeon.get("JEOPSU_NO").replace(/[\-]/g, ""))) {
			await scwin.btn_Johoe_onclick();
		} else {
			scwin.btn_MinwonJeopsuJohoeJogeon_SIISJangaeJohoe_onclick();
		}
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_SubUpdateChk
 * FUNCTION 기능설명 : 데이터셋 변경 여부 체크
*******************************************************************************/ 
scwin.fn_SubUpdateChk = async function(dsObjs, gyeoljaeFg) 
{	
	debugger;
	var v_Msg  = Array();

	if (dsObjs == null || dsObjs.length  == 0) {
		return false;
	}	

	for(var i=0;i<dsObjs.length; i++) {
		console.log(dsObjs[i].getModifiedIndex());
		if (!com.gfn_IsNull(dsObjs[i].getModifiedIndex())) {  // getModifiedIndex : array 리턴		
			v_Msg[0] = "입력된 데이터";
			var conRtn = await com.gfn_Confirm("입력된 데이터를 초기화 하시겠습니까?");
			if(!conRtn){ 	
				return false;
			} 
		}
	}

	scwin.v_initGubunYn = 0 ; 
	div_import_1_q_qa.getWindow().scwin.fn_Init();
	scwin.fn_InitAllDataSet();

	if (gyeoljaeFg) {
		// com.gfn_initGtGyeolJaeInfo();
	}
	scwin.v_initGubunYn = 1 ; 

	return true;	
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_SubSaveEvtSet
 * FUNCTION 기능설명 : 저장이벤트 발생시 다음정보를 기본적으로 세팅 
*******************************************************************************/ 
scwin.fn_SubSaveEvtSet = function(dsObj) {

	if (com.gfn_IsNull(dsObj.get("JEOPSU_NO"))) {

		dsObj.set("MINWON_FG"				 , scwin.v_PMinwonFg);
		dsObj.set("MINWON_DOC_FG"			 , "1");
		dsObj.set("JEOPSU_FG"				 , "1");
		dsObj.set("MINWON_JIKGWON_ONLINE_FG" , "2");
		dsObj.set("CHEORI_JISA_CD"			 , dsObj.get("GWANRI_JISA_CD"));	

		if (com.gfn_IsNull(dsObj.get("FIRST_DAMDANGJA_ID"))) {
			dsObj.set("FIRST_DAMDANGJA_ID", dsObj.get("DAMDANGJA_ID"));
			dsObj.set("FIRST_DAMDANGJA_NM", dsObj.get("DAMDANGJA_NM"));
		}
	}	
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_SubEmailSet
 * FUNCTION 기능설명 : 이메일 정보 세팅 
 * PARAM 정보 : dsObj => 셋팅할 데이터셋, colNms => Email 컬럼명들, smFg => 플래그(Split : 분리, Merge : 병합)
*******************************************************************************/ 
scwin.fn_SubEmailSet = function(dsObj, colNms, smFg){
	var v_Email;
	if(smFg == "Merge") {	
		for(var inx = 0; inx < colNms.length; inx++) {
			if(!com.gfn_IsNull(dsObj.get(colNms[inx] + "1")) &&
			   !com.gfn_IsNull(dsObj.get(colNms[inx] + "2")) ) {
			   v_Email = dsObj.get(colNms[inx] + "1") + "@" + dsObj.get(colNms[inx] + "2");
			   dsObj.set(colNms[inx], v_Email);
			}
		}
	} else if(smFg == "Split") {	
		for(var inx = 0; inx < colNms.length; inx++) {
			if(!com.gfn_IsNull(dsObj.get(colNms[inx]))) {
				v_Email = com.split(dsObj.get(colNms[inx]), "@", "webstyle");
				dsObj.set(colNms[inx] + "1", v_Email[0]);
				dsObj.set(colNms[inx] + "2", v_Email[1]);
			}
		}	
	} 
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_SubMinwonDocCdSet
 * FUNCTION 기능설명 : 민원서류 조회
*******************************************************************************/ 
scwin.fn_SubMinwonDocCdSet = async function(obj, dsObj, v_Flag, nextCom, oldMinwonCd, oldMinwonNm) {
	debugger;
    var v_Param = "";
		v_Param += "v_Minwon_Cd=" + dsObj.get("MINWON_DOC_CD");
		v_Param += " v_Minwon_Fg=" + scwin.v_PMinwonFg;
		v_Param += " v_SayongYN=Y";
		v_Param += " v_MinwonJikGwon_Fg=1";  // 1: 민원서류만 검색 , 2: 직권만 검색  NULL: 둘다	    

	var v_MinwonInfo = Array();
	v_MinwonInfo = await za.cfn_GetMinwonDocInfo(v_Flag, v_Param);

	if (!com.gfn_IsNull(v_MinwonInfo[0])) {

		if (com.gfn_IsNull(oldMinwonCd)) {		
			dsObj.set("MINWON_DOC_CD"	, v_MinwonInfo[0]);
			dsObj.set("MINWON_DOC_NM"	, v_MinwonInfo[1]);
			dsObj.set("TABLE_NM"     	, v_MinwonInfo[7]);
			dsObj.set("SJ_TABLE_NM"	    , v_MinwonInfo[7]);
			dsObj.set("GY_TABLE_NM"	    , v_MinwonInfo[8]);
			dsObj.set("IC_TABLE_NM"	    , v_MinwonInfo[9]);	

			if (!com.gfn_IsNull(v_MinwonInfo[6])) {
			    dsObj.set("PROGRAM_ID"   , v_MinwonInfo[6]); 
			} else {
			    dsObj.set("PROGRAM_ID"   , v_MinwonInfo[5]); 
			}
			nextCom.focus();

		} else {	// 징수화면 민원서류코드 변경에 대한 제약조건체크(보상에서 해당 로직 안탐)

			if (div_import_1_q_qa.getWindow().fn_ChangeMinwonDocCd(oldMinwonCd, v_MinwonInfo[0], v_MinwonInfo[7], v_MinwonInfo[8], v_MinwonInfo[9])){
				dsObj.set("MINWON_DOC_CD"	, v_MinwonInfo[0]);
				dsObj.set("MINWON_DOC_NM"	, v_MinwonInfo[1]);
				dsObj.set("SJ_TABLE_NM"		, v_MinwonInfo[7]);
				dsObj.set("GY_TABLE_NM"		, v_MinwonInfo[8]);
				dsObj.set("IC_TABLE_NM"		, v_MinwonInfo[9]);	
				if (!com.gfn_IsNull(v_MinwonInfo[6])) {
			        dsObj.set("PROGRAM_ID"   , v_MinwonInfo[6]); 
			    }else{
			        dsObj.set("PROGRAM_ID"   , v_MinwonInfo[5]); 
			    }
			} else {
				dsObj.set("MINWON_DOC_CD", oldMinwonCd);
				dsObj.set("MINWON_DOC_NM", oldMinwonNm);
			}
			nextCom.focus();	
		}
		if (!scwin.v_PMinwonDocChkFg) {
			dsObj.set("MINWON_DOC_NM"	, scwin.v_PMinwonDocNm);
			scwin.v_PMinwonDocChkFg = true;
		}
	} else {
		obj.focus();
	}
}

