		} else {//징수화면 민원서류코드 변경에 대한 제약조건체크

			if (div_import_1_q_qa.getWindow().getWindow().fn_ChangeMinwonDocCd(oldMinwonCd, v_MinwonInfo[0], v_MinwonInfo[7], v_MinwonInfo[8], v_MinwonInfo[9])) {
				dsObj.set("MINWON_DOC_CD"	, v_MinwonInfo[0]);
				dsObj.set("MINWON_DOC_NM"	, v_MinwonInfo[1]);
				dsObj.set("SJ_TABLE_NM"		, v_MinwonInfo[7]);
				dsObj.set("GY_TABLE_NM"		, v_MinwonInfo[8]);
				dsObj.set("IC_TABLE_NM"		, v_MinwonInfo[9]);	

				if (!com.gfn_IsNull(v_MinwonInfo[6])) {
			        dsObj.set("PROGRAM_ID"   , v_MinwonInfo[6]); 
			    } else {
			        dsObj.set("PROGRAM_ID"   , v_MinwonInfo[5]); 
			    }
			} else {
				dsObj.set("MINWON_DOC_CD", oldMinwonCd);
				dsObj.set("MINWON_DOC_NM", oldMinwonNm);
			}
			nextCom.focus();	
		}

		if (!scwin.v_PMinwonDocChkFg) {
			dsObj.set("MINWON_DOC_NM"	, scwin.v_PMinwonDocNm);
			scwin.v_PMinwonDocChkFg = true;
		}
	} else {
		obj.focus();
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_SubMinwoninInfoRetrieve
 * FUNCTION 기능설명 : 민원인성명조회 (민원인정보를 조회할 수 있는 화면을 Open)
*******************************************************************************/ 
scwin.fn_SubMinwoninInfoRetrieve = async function(dsObj, curRgno, curCom, nextCom, colNms, vFlag) 
{
	var v_Flag  = vFlag;
    var v_param = "v_Customer_Nm=" + com.trim(curCom.getValue()) +
                  " v_Customer_Rgno=" + com.trim(curRgno.getValue()) +
                  " v_Taa100mt_SearchYn=" + com.trim("Y");

    var v_MinwoninInfo = Array();    
    v_MinwoninInfo = await za.cfn_GetCustomerInfo(v_Flag, v_param);

    if (!com.gfn_IsNull(v_MinwoninInfo[5])) {
		dsObj.set("MINWONIN_NM"				, v_MinwoninInfo[ 5]);
		dsObj.set("MINWONIN_RGNO"			, v_MinwoninInfo[ 6]);
		dsObj.set("MINWONIN_EMAIL"			, v_MinwoninInfo[45]);
		dsObj.set("MINWONIN_DDD"			, v_MinwoninInfo[34]);
		dsObj.set("MINWONIN_TEL1"			, v_MinwoninInfo[35]);
		dsObj.set("MINWONIN_TEL2"			, v_MinwoninInfo[36]);
		dsObj.set("MINWONIN_HP_DDD"			, v_MinwoninInfo[38]);
		dsObj.set("MINWONIN_HP_TEL1"		, v_MinwoninInfo[39]);
		dsObj.set("MINWONIN_HP_TEL2"		, v_MinwoninInfo[40]);
		dsObj.set("MINWONIN_POST"			, v_MinwoninInfo[8 ]);
		dsObj.set("MINWONIN_POST_SER"		, v_MinwoninInfo[9 ]);
		dsObj.set("MINWONIN_GIBON_ADDR"		, v_MinwoninInfo[22]);
		dsObj.set("MINWONIN_SANGSE_ADDR"	, v_MinwoninInfo[23]);
		dsObj.set("MINWONIN_FAX_DDD"		, v_MinwoninInfo[42]);
		dsObj.set("MINWONIN_FAX_TEL1"		, v_MinwoninInfo[43]);
		dsObj.set("MINWONIN_FAX_TEL2"		, v_MinwoninInfo[44]);
		scwin.fn_SubEmailSet(dsObj, colNms, "Split");
		nextCom.focus();
		return "RTN_Y"; 
	} else {
		curCom.focus();
		return "RTN_N" ; 
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_SubPreInfoInit
 * FUNCTION 기능설명 : 민원인정보 초기화
*******************************************************************************/ 
scwin.fn_SubPreInfoInit = function(dsObj, colNm, skipColNm) {
	var v_ColId = "";
	for (var colInx = 0; colInx < dsObj.colcount; colInx++) {
		v_ColId = dsObj.getKey(colInx);
		if(v_ColId == decode(com.gfn_IsNull(skipColNm), 1, "" , skipColNm)) continue;

		if(com.indexOf(v_ColId, colNm) == 0) {
			dsObj.set(v_ColId, "");
		}
	}
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_SubJeopsuFgChk
 * FUNCTION 기능설명 : 접수구분 체크
*******************************************************************************/ 
scwin.fn_SubJeopsuFgChk = async function(v_JeopsuFg) 
{
	if (v_JeopsuFg == "3") {	// 4대보험 민원접수
		if (scwin.v_PMinwonDocCd != "8000" && scwin.v_PMinwonDocCd != "8001" 
		 && scwin.v_PMinwonDocCd != "8002" && scwin.v_PMinwonDocCd != "8003" 
		 && scwin.v_PMinwonDocCd != "8004" && scwin.v_PMinwonDocCd != "8005" 
		 && scwin.v_PMinwonDocCd != "8028"){ // 민원코드 8000~8005, 8028 수정 가능하도록 개선 2014.05.08
			await com.gfn_Alert("4대보험연계접수된 민원(접수구분 3)은 수정할 수 없습니다.\n외부시스템연계민원접수처리화면에서 수정하십시오.");

			return false;
		}	
	} else if (v_JeopsuFg == "4") {	// 토탈민원접수
		if (scwin.v_PMinwonDocCd != "8000" && scwin.v_PMinwonDocCd != "8002" &&
			scwin.v_PMinwonDocCd != "8004" && scwin.v_PMinwonDocCd != "5072" &&
			scwin.v_PMinwonDocCd != "5073" && scwin.v_PMinwonDocCd != "5082" &&
			scwin.v_PMinwonDocCd != "5083") {  // 민원코드 8000,8002,8004 수정 가능하도록 개선 2020.05.26	// 2021.07.23 - by 김재석 : 5073 수정가능하게 개선. // 2021.09.03 - by 김태성 : 5082,5083 추가
			await com.gfn_Alert("토탈서비스로 접수된 민원(접수구분 4)은 수정할 수 없습니다.\n단, 담당자 변경은 외부시스템연계민원접수처리화면에서 가능합니다.");

			return false;
		}
	} else if(v_JeopsuFg == "5") {  // 사무대행기관 접수 
		if(scwin.v_PMinwonDocCd != "8000" && scwin.v_PMinwonDocCd != "8002" 
		&& scwin.v_PMinwonDocCd != "8004") { // 민원코드 8000,8002,8004 수정 가능하도록 개선 2020.05.26
			await com.gfn_Alert("토탈서비스로 접수된 민원(접수구분 5)은 수정할 수 없습니다.\n단, 담당자 변경은 외부시스템연계민원접수처리화면에서 가능합니다.");

			return false;
		}
	} 

	return true;
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_SubCheckRgno
 * FUNCTION 기능설명 : 주민등록번호 체크
*******************************************************************************/ 
scwin.fn_SubCheckRgno = async function(obj, strVal)
{
	var v_Rgno = com.trim(com.replace(strVal, "-", ""));
	var v_Msg = "잘못된 주민등록번호 체계입니다. 계속하시겠습니까?";
	if (!com.gfn_CheckJumin(v_Rgno)) {
		//if(com.gfn_Confirm(v_Msg)) {		
		var conRtn = await com.gfn_Confirm(v_Msg);
		if(conRtn){ 	
			return true;
		} else {
			obj.focus();
			return false;
		}
	} 

	return true;	
}

/*******************************************************************************
 * FUNCTION 명 : scwin.fn_SubUpdateCheckMinwonDocCd
