			var conRtn = await com.gfn_Confirm("민원서류코드를 변경하시겠습니까?");
			if(conRtn){ 	
				// 
			} else {
				scwin.v_PMinwonDocChkFg = false;
			}
		}
	} 

	return scwin.v_PMinwonDocChkFg;
}

